 const pcb=extrude(host.body,s,.8,[0,0,-2.5],materials.plastic(0x186d45,{roughness:.87}),'INA226-1A fixed PCB with genuine mounting reliefs and retaining bore');pcb.userData.role='physical-pcb';
 const metal=materials.metal(0xb6bba9,{roughness:.49}),dark=materials.plastic(0x20231f,{roughness:.85}),ceramic=materials.plastic(0xb3a57d,{roughness:.82}),packages=[];
 // Own U200-1A schematic identifies the packages. Hidden placement is reconstructed,
 // never a measured isolation barrier or a manufacturing PCB/BOM layout.
 const packageLeads={};
 const lead=(x,y,w,z,side,width=.25)=>{const shape=new THREE.Shape(),edge=w/2,pts=[[edge,.3],[edge+.15,.3],[edge+.4,-.02],[edge+.65,-.02],[edge+.65,-.15],[edge+.3,-.15],[edge+.08,.15],[edge,.15]];pts.forEach(([a,b],i)=>i?shape.lineTo(side*a,b):shape.moveTo(side*a,b));shape.closePath();return mesh(host.body,new THREE.ExtrudeGeometry(shape,{depth:width,bevelEnabled:false}).rotateX(Math.PI/2),metal,[x,y+width/2,z],'INA226-1A actual fixed gull-wing package terminal');};
 const ic=(x,y,w,h,z,depth,n,leads,pitch=.65)=>{const body=slab(host.body,w,h,depth,.1,[x,y,z],dark,[],.02);body.name='INA226-1A '+n;packages.push(body);const terminals=[];for(const sign of[-1,1]){const count=Array.isArray(leads)?leads[sign===-1?0:1]:leads;for(let i=0;i<count;i++)terminals.push(lead(x,y+(i-(count-1)/2)*pitch,w,z,sign));}packageLeads[n]=terminals;body.userData={role:'fixed-chip-package',leadCount:terminals.length,installationInferred:true};return body;};
