 const regulators=[ic(-6.4,8.5,1.7,2.9,-1.55,.95,'U3 XC6228D332VR-G measurement-side SOT25 body',[3,2],.65),ic(6.8,-7.4,1.7,2.9,-1.55,.95,'U4 XC6228D332VR-G host-side SOT25 body',[3,2],.65)];
 const shunt=mesh(host.body,new THREE.BoxGeometry(3.2,1.6,.55),dark,[4.9,20.4,-1.425],'INA226-1A R3 80mΩ fixed shunt envelope');shunt.userData={role:'physical-shunt',ohmLabel:'80mR',packageEnvelopeInferred:true,scope:'Physical appearance only,no electrical model;exact installed passive footprint unconfirmed'};const shuntEnds=[];for(const sign of[-1,1])shuntEnds.push(mesh(host.body,new THREE.BoxGeometry(.42,1.6,.6),metal,[4.9+sign*1.42,20.4,-1.4],'INA226-1A shunt metal termination'));
