 for(const[i,n]of[...resistorNames,...capacitorNames,'D1 LESD3Z5.0CMT1G'].entries()){const[x,y]=passivePositions[i],isCap=i>=resistorNames.length&&i<resistorNames.length+capacitorNames.length,part=mesh(host.body,new THREE.BoxGeometry(1.6,.9,.5),isCap?ceramic:dark,[x,y,-1.45],'INA226-1A fixed '+n);part.userData={role:'concealed-passive',inferred:true,scope:'Exact own schematic constituent;hidden package envelope and placement reconstructed'};passives.push(part);if(i<resistorNames.length)resistors.push(part);else if(isCap)capacitors.push(part);else protectionDiode=part;for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.28,.9,.52),metal,[x+sign*.66,y,-1.44],'INA226-1A passive solder end');}

